import importlib.util, sys
spec = importlib.util.spec_from_file_location("duration", "/tmp/<path>")
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
p = m.parse_duration

ok = {
 "1h30m": 5400, " 2d 4h ": 187200, "1.5h": 5400, "1w2d3h4m5s": 788645,
 "1:02:03": 3723, "-45s": -45, "0": 0, "1:30": 90, "1:00:00": 3600, "90:00": 5400,
 "-1h": -3600, "-1:30": -90, "-0s": 0, "-0": 0, "05m": 300, "1.5m": 90, "0.1h": 360,
 "1h 30m": 5400, "1h30m": 5400, "1.0s": 1, "0m": 0, "1w": 604800, "0.25h": 900,
}
bad = [
 "", "   ", "5", "1.5", ".5h", "5.h", "30m1h", "1h1h", "1 h", "1  h", "1h  30m", "1h 30m ",
 "0.3s", "+1h", "- 1h", "1H", "1:60", "1:5", "1:005", "1:30:5", "1:2:03", "1:30:60",
 "1:1:1", "1.5:00", "1 :30", "1h-30m", "h", "--1h", "1x", "1h30", "٣h", "1:-30", "1.5s",
 "1h.5m", "-", "00", "1ms", "1h\t30m",
]
fails = []
for s, v in ok.items():
    try:
        r = p(s)
        if r != v or type(r) is not int: fails.append((s, r, v))
    except Exception as e: fails.append((s, repr(e), v))
for s in bad:
    try:
        r = p(s); fails.append((s, "returned", r))
    except ValueError: pass
    except Exception as e: fails.append((s, repr(e), "ValueError"))
for x in (5, None, b"1h"):
    try: p(x); fails.append((x, "no error", "TypeError"))
    except TypeError: pass
print("FAILURES:", fails or "none")
print("checked", len(ok), "valid and", len(bad), "invalid, plus TypeError cases")
EOF
